def quicksort(arr):
    if len(arr) <= 1:
        return arr
    pivot = arr[0]
    less = [x for x in arr[1:] if x <= pivot]
    more = [x for x in arr[1:] if x > pivot]
    return quicksort(less) + [pivot] + quicksort(more)

print(quicksort([3, 1, 4, 1, 5, 9, 2, 6, 5, 3]))

