from collections.abc import Sequence
from typing import TypeVar

T = TypeVar('T', bound='int | float | str')

def quicksort(arr: Sequence[T]) -> list[T]:
    """Three-way partition quicksort (Dutch national flag)."""
    if len(arr) <= 1:
        return list(arr)
    pivot = arr[len(arr) // 2]
    lo = [x for x in arr if x < pivot]
    eq = [x for x in arr if x == pivot]
    hi = [x for x in arr if x > pivot]
    return quicksort(lo) + eq + quicksort(hi)

print(quicksort([3, 1, 4, 1, 5, 9, 2, 6, 5, 3]))
